(window.__AC=window.__AC||{});__AC["assets4"]=(__AC["assets4"]||'')+"// Глава IV «Зеркальный лес»: реплики (Edge TTS), музыка и звуки (процедурный синтез), текстура соли (Poly Haven, CC0), портрет Солы\nObject.assign(window.ASSETS_LINES,{\"l4_a\": {\"s\": \"avram\", \"t\": \"Ирма, приём… Связь тает. Ты на прямом пути колонистов. Дальше только Пекло. Иди от тени к тени.\"}, \"l4_b\": {\"s\": \"irma\", \"t\": \"Здесь солнце не садится. Значит, и я не сяду.\"}, \"l4_cloak\": {\"s\": \"irma\", \"t\": \"Затвор на солнечном приёмнике. Светлая сторона плаща отразит луч. Только бы не свариться.\"}, \"l4_crate\": {\"s\": \"irma\", \"t\": \"Ящик на уступе. Клюв дотянется. Стащу — и будет ступенька. А заодно и тень.\"}, \"l4_shade\": {\"s\": \"irma\", \"t\": \"Тени башен ползут. Иду вместе с ними.\"}, \"l4_sola1\": {\"s\": \"sola\", \"t\": \"Стой! Не беги по песку — черви слышат шаги и чуют жар. Ты из сумеречных? У тебя есть тень… Как красиво.\"}, \"l4_sola2\": {\"s\": \"irma\", \"t\": \"Я Ирма, обходчица из Орсо. Мне нужно пройти Пекло насквозь.\"}, \"l4_sola3\": {\"s\": \"sola\", \"t\": \"Дед говорил: раньше солнце стояло ниже. Оно ползёт быстрее, чем считают Навигаторы. Зеркала это помнят.\"}, \"l4_take_i\": {\"s\": \"irma\", \"t\": \"Пойдёшь со мной? Только держись в моей тени.\"}, \"l4_take\": {\"s\": \"sola\", \"t\": \"Пойду! Я знаю, где спят черви. Пойду низом — встретимся у зеркал.\"}, \"l4_stay_i\": {\"s\": \"irma\", \"t\": \"Оставайся в лагере. Там, куда я иду, хуже, чем здесь.\"}, \"l4_stay\": {\"s\": \"sola\", \"t\": \"Тогда возьми жар из нашего горна. Твоя Печка полна. И возвращайся.\"}, \"l4_worm_s\": {\"s\": \"sola\", \"t\": \"Ирма, под песком червь! Не беги. Иди тихо, пригнувшись, и остывай на камнях.\"}, \"l4_worm_i\": {\"s\": \"irma\", \"t\": \"Песок дрожит. Что-то идёт на тепло. Тише, Ирма. Тише.\"}, \"l4_mirror_s\": {\"s\": \"sola\", \"t\": \"Я здесь! Зеркала передают свет друг другу. Но нижнее повёрнуто не туда — дёрни рычаг наверху.\"}, \"l4_mirror_i\": {\"s\": \"irma\", \"t\": \"Зеркала колонистов. Нижнее смотрит не туда. Рычаг высоко — Клюв достанет.\"}, \"l4_plate\": {\"s\": \"irma\", \"t\": \"Створку держит плита. Моего веса мало — нужен груз.\"}, \"l4_tide\": {\"s\": \"irma\", \"t\": \"Тень уходит! Солнечный прилив! Бегом к семафору!\"}, \"l4_teo\": {\"s\": \"irma\", \"t\": \"Эта метка… Так метил рельсы только Тео. И краска свежая. Тео… ты жив?\"}, \"l4_sola_end\": {\"s\": \"sola\", \"t\": \"Это знак сумеречного. Он прошёл здесь прошлым летом, к Сангре. Я помню его тень.\"}, \"s7\": {\"s\": \"narr\", \"t\": \"Журнал зеркальщиков: тень у Третьей башни стала короче на ладонь. Навигаторам писали трижды. Ответа не было.\"}, \"s8\": {\"s\": \"narr\", \"t\": \"Расписка Гильдии: зеркальные башни отключить. Свет — только для головных городов. Подпись стёрта солью.\"}, \"e4\": {\"s\": \"irma\", \"t\": \"Тео жив. Орсо ждёт. Впереди Сангра и Звёздный Зал. Значит, туда я и иду.\"}});\nObject.assign(window.ASSETS_AUDIO,{\"m_desert\": \"";